import{z as o,x as n,o as t,c as d,q as l,j as s,D as e,d as A,s as i,S as r,b as E}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"去渣","description":"","frontmatter":{"title":"去渣","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/descum.md","filePath":"litho/descum.md","lastUpdated":1791063341000}'),D={name:"litho/descum.md"};function p(m,a,C,h,u,c){const B=n("Mermaid");return t(),d("div",null,[a[2]||(a[2]=l('<h1 id="去渣" tabindex="-1">去渣 <a class="header-anchor" href="#去渣" aria-label="Permalink to &quot;去渣&quot;">​</a></h1><div class="epigraph"><p>显影后的残膜和脚不是空中像的一部分；去渣用弱氧化或温和等离子体把它们清掉，也会吃掉真 CD。</p><footer>—— 对照 descum / ashing 在显影后、硬掩模开口前的公开位置</footer></div><p><a href="/litho/collapse-mitigation">上一课</a>处理还立着的线。缺口是脚下和孔底的残渣：光学上像桥、电学上开路。本课钉去渣，不把全量胶剥离提前写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>欠显影、BARC 不溶、驻波谷，都会留残胶。SEM 上看见的「关不掉的底」若直接进主刻蚀，选择比可能不够，或把残渣当掩模打出钉。去渣过猛，线宽被吃、LER 升。把残渣全写成剂量不足，会漏掉这一步的独立窗口。</p><p><span class="marginnote">术语翻译：descum（去渣）就是用一轮很弱的氧化等离子体，把显影后贴在孔底和线脚上的几纳米残膜「灰化」掉的手段——它不刻衬底、也不换掩模，只是给显影收尾。英文也叫 light ash，「light」说的就是剂量必须轻。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>典型：短时间 O₂ 或形成气体等离子体，或湿法弱氧化。终点靠时间或光学发射。须与成像胶、SOG、SOC 的选择比匹配——三层堆叠里去渣往往只清成像胶残，停在 SOG。剂量以「残渣消失、CD 损失可接受」为窗。</p>',8)),(t(),s(r,null,{default:e(()=>[i(B,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20RES%5B%22%E6%98%BE%E5%BD%B1%E5%90%8E%E6%AE%8B%E6%B8%A3%22%5D%20--%3E%20DSC%5B%22%E7%9F%AD%E7%AD%89%E7%A6%BB%E5%AD%90%E4%BD%93%20%2F%20%E6%B9%BF%E6%B3%95%22%5D%0A%20%20DSC%20--%3E%20OPEN%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9ABARC%20%2F%20%E7%A1%AC%E6%8E%A9%E6%A8%A1%E5%BC%80%E5%8F%A3%22%5D%0A%20%20DSC%20--%3E%20CD%5B%22CD%20%E6%8D%9F%E5%A4%B1%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[E("span",{class:"marginnote"},"EUV 金属氧化物胶的残渣化学与 CAR 不同，同一 O₂ 去渣可能无效或过刻。换胶要重新定去渣。")],-1)),a[4]||(a[4]=E("p",null,[E("span",{class:"marginnote"},"为什么重要：残渣若带进主刻蚀，衬底就会在残渣处刻不穿，电学上是一根开路的线；而失效排查往往先怀疑刻蚀配方，很少有人回头查显影尾迹与去渣窗口。这一步没做好，后面的「锅」经常分错。")],-1)),a[5]||(a[5]=E("h2",{id:"机制",tabindex:"-1"},[A("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=E("p",null,"残渣薄、真图形厚，短氧化可以在真图形被明显削薄前清底。LER 的高频成分有时被「磨掉」，有时被等离子体粗糙化——要分气体。",-1)),(t(),s(r,null,{default:e(()=>[i(B,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E6%AE%8B%E6%B8%A3%3A%20%E8%96%84%2C%20%E5%87%A0%E7%BA%B3%E7%B1%B3%E9%87%8F%E7%BA%A7%22%5D%20--%3E%20P%5B%22%E5%BC%B1%E6%B0%A7%E5%8C%96%20%2F%20%E7%9F%AD%E7%AD%89%E7%A6%BB%E5%AD%90%E4%BD%93%22%5D%0A%20%20G%5B%22%E7%9C%9F%E5%9B%BE%E5%BD%A2%3A%20%E5%8E%9A%E5%BE%97%E5%A4%9A%22%5D%20--%3E%20P%0A%20%20P%20--%3E%20Q%7B%22%E6%97%B6%E9%97%B4%E5%81%9C%E5%9C%A8%E5%93%AA%3F%22%7D%0A%20%20Q%20--%20%22%E6%AE%8B%E6%B8%A3%E5%88%9A%E6%B8%85%E5%AE%8C%22%20--%3E%20OK%5B%22%E5%BA%95%E5%B9%B2%E5%87%80%2C%20CD%20%E6%8D%9F%E5%A4%B1%E5%8F%AF%E6%8E%A5%E5%8F%97%22%5D%0A%20%20Q%20--%20%22%E7%BB%A7%E7%BB%AD%E8%BD%B0%22%20--%3E%20BAD%5B%22%E7%9C%9F%E7%BA%BF%E8%A2%AB%E5%89%8A%E8%96%84%3A%20CD%20%E7%BC%A9%2C%20LER%20%E5%8D%87%22%5D%0A%20%20OK%20--%3E%20NEXT%5B%22%E5%8F%AF%E8%BF%9B%E4%B8%BB%E5%88%BB%E8%9A%80%22%5D%0A%20%20BAD%20--%3E%20NEXT2%5B%22%E7%AA%97%E5%8F%A3%E6%8A%A5%E5%BA%9F%2C%20%E9%A1%BB%E9%87%8D%E5%AE%9A%E9%85%8D%E6%96%B9%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p><span class="marginnote">常见误区：初学者容易以为去渣时间越长越保险。实际上残渣清完之后，等离子体只会继续均匀削真胶——CD 一直在缩、LER 在涨，而「看不见残渣」这个验收信号不会再变化。所以窗口按「残渣消失、CD 损失还很小」来定，宁短勿长。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不是 <a href="/litho/resist-strip-ash">胶去除</a>。去渣保留图形；剥离去掉全部掩模。下一课硬烤：去渣前后的热，改模量与残留溶剂。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>去渣清显影残，付 CD 损失。</li><li>停层必须与三层选择比一致。</li><li>出处：descum 工艺通识；接续显影与倒塌课。</li></ul>',5))])}const _=o(D,[["render",p]]);export{F as __pageData,_ as default};
